import { useEffect, useRef, useState } from "react";
import {
  createReaderTransportError,
  isReaderTransportError,
  type ReaderLiveTranslationCommitEvent as LiveTranslationCommitEvent,
  type ReaderLiveTranslationPageSnapshot as LiveTranslationPageSnapshot,
  type ReaderLiveTranslationPort,
} from "../contracts/live-translation.js";
import { readerLiveTranslation } from "../external.js";
import {
  EMPTY_LIVE_TRANSLATION_STATE,
  applyLiveTranslationSnapshot,
  decideLiveTranslationSnapshot,
  layoutPageMap,
  type LiveTranslationState,
} from "../shared/data/live-translation-state.js";
import { isFinishedJobStatus } from "@retainpdf/domain/job";

const LAYOUT_RETRY_MS = [250, 500, 1_000, 2_000, 4_000];
const SNAPSHOT_RETRY_MS = [80, 160, 320, 640, 1_000, 1_500];
const STREAM_RETRY_MS = [250, 500, 1_000, 2_000, 4_000, 5_000];

function wait(ms: number, signal: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal.aborted) {
      reject(new DOMException("Aborted", "AbortError"));
      return;
    }
    const onAbort = () => {
      clearTimeout(timer);
      reject(new DOMException("Aborted", "AbortError"));
    };
    const timer = setTimeout(() => {
      signal.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    signal.addEventListener("abort", onAbort, { once: true });
  });
}

function errorCode(error: unknown): string {
  return isReaderTransportError(error) ? `${error.code || ""}`.trim() : "";
}

function errorMessage(error: unknown, fallback: string): string {
  const code = errorCode(error);
  if (code === "LIVE_TRANSLATION_PAGE_NOT_COMMITTED") {
    return "尚未收到可显示的页面译文";
  }
  if (code === "LIVE_TRANSLATION_LAYOUT_NOT_READY") {
    return "正在等待 OCR 版面数据";
  }
  const message = `${(error as Error)?.message || ""}`.trim();
  return message || fallback;
}

async function fetchMatchingPage(
  jobId: string,
  event: LiveTranslationCommitEvent,
  current: LiveTranslationState,
  signal: AbortSignal,
  port: ReaderLiveTranslationPort,
): Promise<LiveTranslationPageSnapshot> {
  let lastError: unknown = null;
  for (let attempt = 0; ; attempt += 1) {
    try {
      const snapshot = await port.fetchPage(jobId, event.page_idx, { signal });
      if (decideLiveTranslationSnapshot(current.pagesByPage.get(event.page_idx), event, snapshot) !== "retry") {
        return snapshot;
      }
      lastError = createReaderTransportError(
        "Authoritative page snapshot has not reached the event generation",
        409,
        "LIVE_TRANSLATION_SNAPSHOT_UNAVAILABLE",
      );
    } catch (error) {
      if ((error as Error)?.name === "AbortError") throw error;
      lastError = error;
      const code = errorCode(error);
      if (code && ![
        "LIVE_TRANSLATION_PAGE_NOT_COMMITTED",
        "LIVE_TRANSLATION_SNAPSHOT_UNAVAILABLE",
      ].includes(code)) throw error;
    }
    const delay = SNAPSHOT_RETRY_MS[Math.min(attempt, SNAPSHOT_RETRY_MS.length - 1)];
    await wait(delay, signal);
    if (attempt >= SNAPSHOT_RETRY_MS.length + 2) throw lastError;
  }
}

export type UseLiveTranslationOptions = {
  jobId: string;
  /** Authoritative status owned and refreshed by the Reader session. */
  jobStatus: string;
  enabled: boolean;
  /** Test/embedded-host override; production uses the registered Reader adapter. */
  liveTranslationPort?: ReaderLiveTranslationPort | null;
};

export function useLiveTranslation({
  jobId,
  jobStatus,
  enabled,
  liveTranslationPort = undefined,
}: UseLiveTranslationOptions): LiveTranslationState {
  const [state, setState] = useState<LiveTranslationState>(EMPTY_LIVE_TRANSLATION_STATE);
  const stateRef = useRef(state);
  const stateJobIdRef = useRef("");
  stateRef.current = state;

  const normalizedJobId = `${jobId || ""}`.trim();
  const normalizedJobStatus = `${jobStatus || ""}`.trim().toLowerCase();
  const terminalStatus = isFinishedJobStatus(normalizedJobStatus)
    ? normalizedJobStatus
    : "";

  useEffect(() => {
    if (!enabled || !normalizedJobId) {
      stateJobIdRef.current = "";
      stateRef.current = EMPTY_LIVE_TRANSLATION_STATE;
      setState(EMPTY_LIVE_TRANSLATION_STATE);
      return;
    }

    const port = liveTranslationPort === undefined ? readerLiveTranslation() : liveTranslationPort;
    const sameJob = stateJobIdRef.current === normalizedJobId;
    stateJobIdRef.current = normalizedJobId;
    if (!port) {
      const unavailableState: LiveTranslationState = {
        ...(sameJob ? stateRef.current : EMPTY_LIVE_TRANSLATION_STATE),
        connection: terminalStatus ? "terminal" : "unavailable",
        jobStatus: normalizedJobStatus,
        error: "实时译文暂不可用",
      };
      stateRef.current = unavailableState;
      setState(unavailableState);
      return;
    }
    const abort = new AbortController();
    let layoutReady = false;
    // A failed/cancelled translation is a paused pipeline, not a failed reader.
    // Keep already committed pages and replay durable SSE history on a fresh load.
    const connectingState: LiveTranslationState = {
      ...(sameJob ? stateRef.current : EMPTY_LIVE_TRANSLATION_STATE),
      connection: terminalStatus ? "terminal" : "connecting",
      jobStatus: normalizedJobStatus,
      error: "",
    };
    stateRef.current = connectingState;
    setState(connectingState);

    const publish = (updater: (current: LiveTranslationState) => LiveTranslationState) => {
      if (abort.signal.aborted) return;
      setState((current) => {
        const next = updater(current);
        stateRef.current = next;
        return next;
      });
    };

    const loadLayout = async () => {
      let retry = 0;
      while (!abort.signal.aborted) {
        try {
          const layout = await port.fetchLayout(normalizedJobId, { signal: abort.signal });
          layoutReady = true;
          publish((current) => ({
            ...current,
            layoutByPage: layoutPageMap(layout),
            jobStatus: normalizedJobStatus,
            error: "",
          }));
          return;
        } catch (error) {
          if ((error as Error)?.name === "AbortError") return;
          const layoutErrorCode = errorCode(error);
          // 没有业务 code 的一律当作传输层故障（`TypeError: Failed to fetch`、
          // 代理 502、API 重启…），这些恰恰是最该重试的。此前只认
          // LAYOUT_NOT_READY 可重试，于是打开文档时网络抖一下就被判永久失败：
          // publish 成 unavailable 后直接 return，stream() 因 !layoutReady 立刻
          // 退出，SSE 根本不会打开，而 UI 上没有任何重试入口——只能刷新页面。
          const canRetry = layoutErrorCode === "LIVE_TRANSLATION_LAYOUT_NOT_READY"
            || !layoutErrorCode;
          if (!canRetry) {
            publish((current) => ({
              ...current,
              connection: terminalStatus ? "terminal" : "unavailable",
              jobStatus: normalizedJobStatus,
              error: errorMessage(error, "实时译文暂不可用"),
            }));
            return;
          }
          if (terminalStatus) {
            publish((current) => ({
              ...current,
              connection: "terminal",
              jobStatus: normalizedJobStatus,
              error: "",
            }));
            return;
          }
          publish((current) => ({
            ...current,
            connection: "connecting",
            jobStatus: normalizedJobStatus,
            error: errorMessage(error, "正在等待 OCR 版面数据"),
          }));
          await wait(LAYOUT_RETRY_MS[Math.min(retry, LAYOUT_RETRY_MS.length - 1)], abort.signal).catch(() => {});
          retry += 1;
        }
      }
    };

    const stream = async () => {
      await loadLayout();
      if (!layoutReady || abort.signal.aborted) return;
      let reconnect = 0;
      while (!abort.signal.aborted) {
        if (!terminalStatus) {
          publish((current) => ({
            ...current,
            connection: current.lastSeq > 0 ? "reconnecting" : "connecting",
            jobStatus: normalizedJobStatus,
            // 保留已有错误：首页还没提交（lastSeq 为 0）时恰恰是最容易出错的阶段，
            // 此前这里把它清成空串，UI 于是一直显示「连接中」，用户看到的是
            // "正在努力"，实际可能已经在反复失败。
            error: current.error,
          }));
        }
        try {
          await port.streamEvents(normalizedJobId, {
            afterSeq: stateRef.current.lastSeq,
            signal: abort.signal,
            onEvent: async (event) => {
              if (event.seq <= stateRef.current.lastSeq) return;
              let snapshot: LiveTranslationPageSnapshot;
              try {
                snapshot = await fetchMatchingPage(
                  normalizedJobId,
                  event,
                  stateRef.current,
                  abort.signal,
                  port,
                );
              } catch (error) {
                if ((error as Error)?.name === "AbortError" || abort.signal.aborted) throw error;
                // 这一页的权威快照始终追不上事件（后端还没落库、或 sha256 对不上）。
                // 此前这里把异常抛出去，会击穿整条 SSE；而重连用的 afterSeq 取自
                // 从未推进的 lastSeq，于是同一个事件被无限重放——约每 8.5 秒 9 次
                // 请求，永远不前进，期间整条流还被 await 堵住，后面所有页的译文
                // 一起卡住。改为放弃这一页、推进游标，让后续页继续流下去。
                publish((current) => ({
                  ...current,
                  lastSeq: Math.max(current.lastSeq, event.seq),
                  error: errorMessage(error, "部分页面的实时译文暂时取不到"),
                }));
                return;
              }
              publish((current) => {
                const next = applyLiveTranslationSnapshot(current, event, snapshot);
                return terminalStatus
                  ? {
                    ...next,
                    connection: "terminal",
                    jobStatus: normalizedJobStatus,
                  }
                  : {
                    ...next,
                    jobStatus: normalizedJobStatus,
                  };
              });
              reconnect = 0;
            },
          });
        } catch (error) {
          if ((error as Error)?.name === "AbortError" || abort.signal.aborted) return;
          publish((current) => ({
            ...current,
            connection: terminalStatus ? "terminal" : "reconnecting",
            jobStatus: normalizedJobStatus,
            error: errorMessage(error, "实时译文连接已中断，正在重连"),
          }));
        }
        if (abort.signal.aborted) return;
        if (terminalStatus) {
          publish((current) => ({
            ...current,
            connection: "terminal",
            jobStatus: normalizedJobStatus,
          }));
          return;
        }
        await wait(STREAM_RETRY_MS[Math.min(reconnect, STREAM_RETRY_MS.length - 1)], abort.signal).catch(() => {});
        reconnect += 1;
      }
    };

    void stream();
    return () => abort.abort();
  }, [enabled, liveTranslationPort, normalizedJobId, terminalStatus]);

  return state;
}
